def find_demlo(n_str):
    n = int(n_str)

    if n < 1:
        return ""

    digits = len(str(n))

    result = []

    for i in range(1, digits + 1):
        val = str(i * n)
        result.append(val)

    for i in range(digits - 1, 0, -1):
        val = str(i * n)
        result.append(val)

    return "".join(result)

