def max_product(arr, n):
    # Initialize the dp array where each element is the product of itself initially
    dp = arr[:]

    # Iterate over each element in the array starting from the second one
    for i in range(1, n):
        # Check all previous elements to find the increasing subsequence
        for j in range(i):
            if arr[i] > arr[j]:
                # Update the dp value at index i by considering the product including arr[j]
                dp[i] = max(dp[i], dp[j] * arr[i])

    # The result is the maximum value in the dp array which represents the max product of an increasing subsequence
    return max(dp)

