def hungarian(cost_matrix):
    n = len(cost_matrix)

    # Make a copy to avoid modifying original
    cost = [row[:] for row in cost_matrix]

    # Step 1: Row reduction
    for i in range(n):
        min_val = min(cost[i])
        for j in range(n):
            cost[i][j] -= min_val

    # Step 2: Column reduction
    for j in range(n):
        min_val = min(cost[i][j] for i in range(n))
        for i in range(n):
            cost[i][j] -= min_val

    # Assignment tracking
    assignment = [-1] * n  # job assigned to each worker
    job_assigned_to_worker = [-1] * n  # which worker is assigned to each job

    # Find initial assignments (zeros)
    for i in range(n):
        for j in range(n):
            if cost[i][j] == 0 and assignment[i] == -1:
                # Check if this column is free
                if job_assigned_to_worker[j] == -1:
                    assignment[i] = j
                    job_assigned_to_worker[j] = i
                    break

    # If not all workers assigned, use augmenting paths
    for i in range(n):
        if assignment[i] == -1:
            # Try to find an augmenting path
            parent = [-1] * n  # parent column for each row
            visited_col = [False] * n

            queue = []
            for j in range(n):
                if cost[i][j] == 0:
                    queue.append(j)
                    visited_col[j] = True
                    parent[j] = -1

            found = False
            while queue and not found:
                col = queue.pop(0)

                # Find a row with zero in this column that's assigned to something
                for r in range(n):
                    if cost[r][col] == 0 and assignment[r] != -1:
                        next_col = assignment[r]
                        if not visited_col[next_col]:
                            visited_col[next_col] = True
                            parent[next_col] = col
                            queue.append(next_col)

                            # If we found an unassigned row, augment the path
                            for c in range(n):
                                if cost[c][next_col] == 0 and assignment[c] == -1:
                                    # Augment along this path
                                    curr = next_col
                                    while curr != -1:
                                        prev_row = job_assigned_to_worker[curr]
                                        assignment[prev_row] = curr
                                        job_assigned_to_worker[curr] = prev_row
                                        found = True
                                        break
                                    if found:
                                        break

            # If still not assigned, try direct zero finding
            for j in range(n):
                if cost[i][j] == 0 and assignment[i] == -1:
                    assignment[i] = j
                    job_assigned_to_worker[j] = i
                    break

    # Calculate total cost
    min_cost = sum(cost_matrix[i][assignment[i]] for i in range(n))

    return min_cost, assignment
